package dev.pocketengine.runtime.models;
import dev.pocketengine.core.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
public final class StepModelRoutingTest {
 private static ModelConfig model(String id){return new ModelConfig("https://fixture.invalid/v1","fixture-secret",id,false,8,10);}
 private static JSONObject app()throws Exception{return new JSONObject().put("packageName","fixture.eval");}
 private static void read(StepModelRouting.Session session)throws Exception{session.after("phone_observe",new JSONObject(),new JSONObject().put("ok",true),app());}
 private static JSONObject tool(String name)throws Exception{return new JSONObject().put("tool_calls",new JSONArray().put(new JSONObject().put("function",new JSONObject().put("name",name).put("arguments","{}"))));}
 @Test public void defaultAndUnavailableOptInKeepTheOriginalMain()throws Exception {ModelConfig main=model("main");StepModelRouting.install(null);assertSame(main,StepModelRouting.forRun(main,new RunControl()).pick(3,app(),0));StepModelRouting.install(c->{throw new IllegalStateException();});assertSame(main,StepModelRouting.forRun(main,new RunControl()).pick(3,app(),0));StepModelRouting.install(null);}
 @Test public void disabledRoutingStillRemovesOnlyItsNativeCarrierFromWire()throws Exception {StepModelRouting.install(null);var session=StepModelRouting.forRun(model("main"),new RunControl());JSONArray history=new JSONArray().put(new JSONObject().put("role","assistant").put("provider_data",new JSONObject().put("opaque","retained")).put("nativeStepModelOrigin",session.origin()));JSONObject wire=session.wireMessages(history).getJSONObject(0);assertFalse(wire.has("nativeStepModelOrigin"));assertTrue(wire.has("provider_data"));assertTrue(history.getJSONObject(0).has("nativeStepModelOrigin"));}
 @Test public void twoObservedReadsThenUnsafeLightDecisionReturnsToMainWithoutDispatch()throws Exception {ModelConfig main=model("main"),light=model("light");StepModelRouting.install(c->light);try{var session=StepModelRouting.forRun(main,new RunControl());assertSame(main,session.pick(0,app(),0));read(session);assertSame(main,session.pick(1,app(),0));read(session);assertSame(light,session.pick(2,app(),0));assertFalse(session.accept(tool("phone_tap")));assertSame(main,session.pick(3,app(),0));assertSame(main,session.pick(4,app(),0));}finally{StepModelRouting.install(null);}}
 @Test public void pauseOrNewAppResetTheStreak()throws Exception {ModelConfig main=model("main"),light=model("light");StepModelRouting.install(c->light);try{var session=StepModelRouting.forRun(main,new RunControl());session.pick(0,app(),0);read(session);session.pick(1,app(),0);read(session);assertSame(main,session.pick(2,app(),1));read(session);assertSame(main,session.pick(3,new JSONObject().put("packageName","other.eval"),1));}finally{StepModelRouting.install(null);}}
 @Test public void foreignOpaqueIsRemovedOnlyFromWireAndOwnMainOpaqueIsRetained()throws Exception {ModelConfig main=model("main"),light=model("light");StepModelRouting.install(c->light);try{var session=StepModelRouting.forRun(main,new RunControl());session.pick(0,app(),0);JSONObject origin=session.origin();JSONArray history=new JSONArray().put(new JSONObject().put("role","assistant").put("provider_data",new JSONObject().put("private","opaque")).put("nativeStepModelOrigin",origin));assertTrue(session.wireMessages(history).getJSONObject(0).has("provider_data"));read(session);session.pick(1,app(),0);read(session);session.pick(2,app(),0);assertFalse(session.wireMessages(history).getJSONObject(0).has("provider_data"));assertTrue(history.getJSONObject(0).has("provider_data"));assertTrue(session.accept(tool("phone_observe")));assertFalse(session.accept(new JSONObject().put("content","finished")));}finally{StepModelRouting.install(null);}}
 @Test public void currentNativeQueryNamesWorkAndUnmetWaitIsNotASuccess()throws Exception {ModelConfig main=model("main"),light=model("light");StepModelRouting.install(c->light);try{var session=StepModelRouting.forRun(main,new RunControl());session.pick(0,app(),0);session.after("phone_query",new JSONObject(),new JSONObject().put("ok",true),app());session.pick(1,app(),0);session.after("phone_query",new JSONObject(),new JSONObject().put("ok",true),app());assertSame(light,session.pick(2,app(),0));assertTrue(session.accept(tool("phone_query")));assertTrue(session.accept(tool("browser_task_observe")));session.after("phone_condition_wait",new JSONObject(),new JSONObject().put("ok",true).put("matched",false),app());assertSame(main,session.pick(3,app(),0));}finally{StepModelRouting.install(null);}}
 @Test public void originalTerminalOnlyBoundaryKeepsMainAndAcceptsItsFinalAnswer()throws Exception {ModelConfig main=model("main"),light=model("light");StepModelRouting.install(c->light);try{var session=StepModelRouting.forRun(main,new RunControl());session.pick(0,app(),0);read(session);session.pick(1,app(),0);read(session);assertSame(light,session.pick(2,app(),0));assertSame(main,session.pick(3,app(),0,false));assertFalse(session.usingLight());assertTrue(session.accept(new JSONObject().put("content","bounded final answer")));}finally{StepModelRouting.install(null);}}
}
